// Pure JS HMAC-SHA256 — n8n vm2 blocks require('crypto')
// Canonical: sign JSON.stringify(parsedBody) [compact, no spaces] — matches JS JSON.stringify
const SECRET = "***REDACTED_HMAC_SECRET***";

function rotr(n, x) { return (x >>> n) | (x << (32 - n)); }
function ch(x,y,z){ return (x & y) ^ (~x & z); }
function maj(x,y,z){ return (x & y) ^ (x & z) ^ (y & z); }
function sigma0(x){ return rotr(2,x) ^ rotr(13,x) ^ rotr(22,x); }
function sigma1(x){ return rotr(6,x) ^ rotr(11,x) ^ rotr(25,x); }
function gamma0(x){ return rotr(7,x) ^ rotr(18,x) ^ (x >>> 3); }
function gamma1(x){ return rotr(17,x) ^ rotr(19,x) ^ (x >>> 10); }

function sha256(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const bitLen = l * 8;
  const withOne = l + 1;
  let padLen = withOne % 64;
  if (padLen > 56) padLen = 64 - padLen + 56; else padLen = 56 - padLen;
  const total = withOne + padLen + 8;
  const msg = new Uint8Array(total);
  msg.set(bytes, 0);
  msg[l] = 0x80;
  const view = new DataView(msg.buffer);
  view.setUint32(total - 8, Math.floor(bitLen / 0x100000000), false);
  view.setUint32(total - 4, bitLen >>> 0, false);
  const W = new Uint32Array(64);
  for (let i = 0; i < total; i += 64) {
    for (let t = 0; t < 16; t++) W[t] = view.getUint32(i + t * 4, false);
    for (let t = 16; t < 64; t++) W[t] = (gamma1(W[t-2]) + W[t-7] + gamma0(W[t-15]) + W[t-16]) >>> 0;
    let [a,b,c,d,e,f,g,h] = H;
    for (let t = 0; t < 64; t++) {
      const T1 = (h + sigma1(e) + ch(e,f,g) + K[t] + W[t]) >>> 0;
      const T2 = (sigma0(a) + maj(a,b,c)) >>> 0;
      h = g; g = f; f = e; e = (d + T1) >>> 0;
      d = c; c = b; b = a; a = (T1 + T2) >>> 0;
    }
    H = [(H[0]+a)>>>0,(H[1]+b)>>>0,(H[2]+c)>>>0,(H[3]+d)>>>0,(H[4]+e)>>>0,(H[5]+f)>>>0,(H[6]+g)>>>0,(H[7]+h)>>>0];
  }
  const out = new Uint8Array(32);
  const ov = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) ov.setUint32(i * 4, H[i], false);
  return out;
}

function utf8Bytes(str) {
  const s = String(str);
  const arr = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c < 0x80) arr.push(c);
    else if (c < 0x800) { arr.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f)); }
    else if (c >= 0xd800 && c <= 0xdbff) {
      i++; const c2 = s.charCodeAt(i);
      const u = 0x10000 + ((c & 0x3ff) << 10) + (c2 & 0x3ff);
      arr.push(0xf0 | (u >> 18), 0x80 | ((u >> 12) & 0x3f), 0x80 | ((u >> 6) & 0x3f), 0x80 | (u & 0x3f));
    } else {
      arr.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
    }
  }
  return new Uint8Array(arr);
}

function hmacSha256Hex(keyStr, msgStr) {
  let key = utf8Bytes(keyStr);
  if (key.length > 64) key = sha256(key);
  const kpad = new Uint8Array(64);
  kpad.set(key);
  const ipad = new Uint8Array(64);
  const opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) { ipad[i] = kpad[i] ^ 0x36; opad[i] = kpad[i] ^ 0x5c; }
  const msg = utf8Bytes(msgStr);
  const inner = new Uint8Array(64 + msg.length);
  inner.set(ipad, 0); inner.set(msg, 64);
  const innerHash = sha256(inner);
  const outer = new Uint8Array(64 + 32);
  outer.set(opad, 0); outer.set(innerHash, 64);
  const dig = sha256(outer);
  let hex = '';
  for (let i = 0; i < dig.length; i++) hex += dig[i].toString(16).padStart(2, '0');
  return hex;
}

function safeEq(a, b) {
  const A = String(a); const B = String(b);
  if (A.length !== B.length) return false;
  let r = 0;
  for (let i = 0; i < A.length; i++) r |= A.charCodeAt(i) ^ B.charCodeAt(i);
  return r === 0;
}

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const signature = String(headers['x-lyra-signature'] || headers['X-Lyra-Signature'] || '').trim().toLowerCase();

// Canonical: JSON.stringify(body) is compact (no spaces) — Next.js must sign the same
const candidates = [];
const compact = JSON.stringify(body);
candidates.push(compact);

// rawBody if present (byte-accurate of original request)
if (typeof item.rawBody === 'string' && item.rawBody.length) {
  candidates.push(item.rawBody);
} else if (item.rawBody && item.rawBody.data && Array.isArray(item.rawBody.data)) {
  let s = '';
  for (let i = 0; i < item.rawBody.data.length; i++) s += String.fromCharCode(item.rawBody.data[i]);
  candidates.push(s);
}

let valid = false;
for (const c of candidates) {
  if (!c) continue;
  if (safeEq(hmacSha256Hex(SECRET, c), signature)) { valid = true; break; }
}

if (!valid) {
  return [{
    json: {
      ok: false,
      error: 'invalid_signature',
      reply: "I could not verify that request. Please refresh the page or use the contact form.",
      intent: 8,
      confidence: 1,
      handoff: 'form',
      _reject: true,
    }
  }];
}

const message = String(body.message || body.text || '').slice(0, 2000).trim();
const history = Array.isArray(body.history) ? body.history.slice(-12) : [];
const sessionId = String(body.sessionId || body.session_id || 'anon').slice(0, 128);
const pageUrl = String(body.pageUrl || body.page || '').slice(0, 500);

if (!message) {
  return [{
    json: {
      ok: false,
      error: 'empty_message',
      reply: "Send a short message and I will help — or book a free consultation on the contact page.",
      intent: 1,
      confidence: 1,
      handoff: null,
      _reject: true,
    }
  }];
}

return [{
  json: {
    ok: true,
    message: message,
    history: history,
    sessionId: sessionId,
    pageUrl: pageUrl,
    _reject: false,
  }
}];

const SYSTEM = "You are Lyra, the AI guide for Lyra Group (Pty) Ltd — a professional, female-owned debt collection agency in Johannesburg, South Africa.

STORYBRAND ROLE
- The visitor is the HERO (SME owner owed money).
- You are the GUIDE — warm, compliant, confident, never aggressive.
- South African English. No US/UK spellings where SA differs. No jargon without plain explanation.

HARD RULES
1. Never invent legal outcomes, guaranteed collection amounts, or fake case results.
2. Never give formal legal advice — you educate and guide toward a free consultation.
3. Never discuss specific debtor harassment tactics. Stay POPIA / Debt Collectors Act compliant.
4. If asked about a live debtor dispute, account status, or personal case detail → handoff.
5. Keep replies short: 2–4 sentences unless they ask for detail.
6. End most replies with one helpful question OR a clear next step.
7. Primary CTA: free consultation at /contact. WhatsApp handoff when they want a human.

