OUTPUT FORMAT — return ONLY valid JSON, no markdown fences:
{
  "intent": <1-8>,
  "confidence": <0.0-1.0>,
  "reply": "<visitor-facing message>",
  "handoff": null | "whatsapp" | "form"
}

Handoff rules:
- intent 6 with clear booking intent → "form" (or whatsapp if they prefer chat)
- intent 7 or 8 → "whatsapp" preferred, else "form"
- otherwise null
";

const prev = $input.first().json;
if (prev._reject) {
  return [{ json: prev }];
}

const history = Array.isArray(prev.history) ? prev.history : [];
const messages = [{ role: 'system', content: SYSTEM }];

for (const h of history) {
  if (!h || !h.role || !h.content) continue;
  const role = h.role === 'assistant' ? 'assistant' : 'user';
  messages.push({ role: role, content: String(h.content).slice(0, 1500) });
}

messages.push({
  role: 'user',
  content: 'Page: ' + (prev.pageUrl || 'unknown') + '
Session: ' + prev.sessionId + '

Visitor message:
' + prev.message
});

// Prefer OpenAI gpt-4o-mini (OPENAI_API_KEY is real OpenAI key).
// Fallback path: if Together MiniMax is configured later, swap model + URL.
return [{
  json: {
    ok: true,
    message: prev.message,
    sessionId: prev.sessionId,
    pageUrl: prev.pageUrl,
    _reject: false,
    llmBody: {
      model: 'MiniMaxAI/MiniMax-M3',
      messages: messages,
      temperature: 0.4,
      max_tokens: 700
    }
  }
}];

const raw = $input.first().json;
let text = '';

// OpenAI / Together compatible
if (raw.choices && raw.choices[0] && raw.choices[0].message) {
  text = raw.choices[0].message.content || '';
} else if (raw.error) {
  // surface soft fallback
  text = '';
} else if (typeof raw.content === 'string') {
  text = raw.content;
} else if (raw.output) {
  text = typeof raw.output === 'string' ? raw.output : JSON.stringify(raw.output);
} else {
  text = JSON.stringify(raw);
}

text = String(text).trim();
text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

let parsed = null;
try { parsed = JSON.parse(text); } catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) { parsed = null; } }
}

if (!parsed || typeof parsed.reply !== 'string') {
  const fallback = "I am here to help with debt recovery questions. Would you like a free consultation, or shall I explain how No Collection. No Fee. works?";
  return [{ json: { ok: true, intent: 1, confidence: 0.3, reply: fallback, handoff: null } }];
}

let intent = parseInt(parsed.intent, 10);
if (!(intent >= 1 && intent <= 8)) intent = 1;
let handoff = parsed.handoff;
if (handoff !== 'whatsapp' && handoff !== 'form') handoff = null;
if ((intent === 7 || intent === 8) && !handoff) handoff = 'form';
if (intent === 6 && !handoff) handoff = 'form';

const reply = String(parsed.reply || '').replace(/\*\*/g, '').trim().slice(0, 2000);

return [{
  json: {
    ok: true,
    intent: intent,
    confidence: typeof parsed.confidence === 'number' ? parsed.confidence : 0.7,
    reply: reply || "How can I help you recover what you are owed?",
    handoff: handoff,
  }
}];

const j = $input.first().json;
const labels = {
  1: 'GREETING_FAQ',
  2: 'SERVICES',
  3: 'PRICING',
  4: 'COMPLIANCE',
  5: 'PROCESS',
  6: 'LEAD_CAPTURE',
  7: 'CASE_SPECIFIC',
  8: 'ESCALATE_HUMAN',
};
const intent = j.intent || 1;
let handoff = j.handoff;
if (intent === 6 && !handoff) handoff = 'form';
if ((intent === 7 || intent === 8) && !handoff) handoff = 'whatsapp';

return [{
  json: {
    ok: true,
    intent: intent,
    intent_label: labels[intent] || 'GREETING_FAQ',
    confidence: j.confidence != null ? j.confidence : 0.7,
    reply: j.reply,
    handoff: handoff,
    branch: intent,
  }
}];
